import torch, os
cache = '/root/autodl-tmp/crm_cache/'
for bench in ['spatial', 'object']:
    path = os.path.join(cache, bench)
    if os.path.exists(path):
        files = sorted(os.listdir(path))
        if not files:
            print(f'{bench}: EMPTY')
            continue
        for f in files:
            fp = os.path.join(path, f)
            if f.endswith('.pt'):
                t = torch.load(fp, map_location='cpu', weights_only=True)
                if isinstance(t, torch.Tensor):
                    print(f'{bench}/{f}: shape={t.shape}, dtype={t.dtype}')
                elif isinstance(t, dict):
                    print(f'{bench}/{f}: dict with keys={list(t.keys())[:5]}')
                elif isinstance(t, list):
                    print(f'{bench}/{f}: list len={len(t)}')
                else:
                    print(f'{bench}/{f}: type={type(t).__name__}')
    else:
        print(f'{bench}: NOT FOUND')
"
